<script lang="ts">
 import {onMount,onDestroy,tick} from 'svelte';
 import {open,save,confirm} from '@tauri-apps/plugin-dialog';
 import {listen} from '@tauri-apps/api/event';import {invoke} from '@tauri-apps/api/core';import {getCurrentWebviewWindow} from '@tauri-apps/api/webviewWindow';import {openUrl,revealItemInDir} from '@tauri-apps/plugin-opener';
 import {Users,Github,FileText,Plus,Search,Grid2X2,Clock3,Settings2,PanelLeft,ChevronLeft,ChevronRight,ZoomIn,ZoomOut,Download,Printer,Undo2,Redo2,Highlighter,Type,Image,PenLine,MessageSquare,MousePointer2,List,Layers,Check,CheckCircle2,X,XCircle,ArrowUpRight,ArrowRight,FolderOpen,Sun,Moon,Monitor,Command,ShieldCheck,ScanText,Merge,Scissors,RotateCw,Minimize2,BookOpen,SlidersHorizontal,ChevronDown,AlignLeft,SquareCheck,LoaderCircle} from 'lucide-svelte';
 import {WorkQueue} from './lib/work-queue';
 import {api,native} from './lib/api';import {tools,groups,toolById} from './lib/catalog';import type {DocumentSession,Task,Tool,Language,Outline} from './lib/types';import ThumbnailPages from './lib/ThumbnailPages.svelte';import ReaderPages from './lib/ReaderPages.svelte';import ToolDialog from './lib/ToolDialog.svelte';import CollaborationDialog from './lib/CollaborationDialog.svelte';
 const isMac=/Mac/.test(navigator.platform);
 const readSetting=(key:string,fallback:string)=>{try{return localStorage.getItem(key)||fallback;}catch{return fallback;}};
 let lang=$state<Language>(readSetting('bpdf-language','zh')as Language);let theme=$state(readSetting('bpdf-theme','system'));const t=(zh:string,en:string)=>lang==='zh'?zh:en;
 let collaborationDraft=$state({address:'',code:'',initialized:false});let showCollaboration=$state(false);let rooms=$state<Record<string,{role:string;invitation?:string;error?:string;lastSync?:number;failures?:number;nextRetry?:number;syncing?:boolean}>>({});const syncQueue=new WorkQueue(2);const roomSyncs=new Set<string>();let drafts=$state<Record<string,string>>({});let githubUrl=$state((readSetting('bpdf-github','')||'https://github.com/Starry331/BetterPDF'));let section=$state('home');let docs=$state<DocumentSession[]>([]);let activeId=$state('');const active=$derived(docs.find(d=>d.id===activeId));
 let taskList=$state<Task[]>([]);let selectedTool=$state<Tool|null>(null);let toolInputs=$state<string[]>([]);let query=$state('');let category=$state('all');let showSettings=$state(false);let toast=$state('');let opening=$state(false);let caps=$state<Record<string,boolean>>({});let dropActive=$state(false);
 let editTools=$state(false);let sidebar=$state(true);let sideTab=$state('pages');let page=$state(0);let scale=$state(.9);let view=$state('continuous');let mode=$state('read');let searchQuery=$state('');let hits=$state<{page:number;quads:number[][]}[]>([]);let searching=$state(false);let editor=$state<Record<string,any>|null>(null);let editing=$state(false);let passwordPath=$state('');let password=$state('');let passwordError=$state('');
 let recent=$state<{path:string;name:string;date:string}[]>([]);let pageView=$state<ReaderPages>();let viewport=$state<HTMLDivElement>();let toastTimer:ReturnType<typeof setTimeout>;
 const running=$derived(taskList.filter(t=>t.state==='queued'||t.state==='running').length);
 const filteredTools=$derived(tools.filter(x=>(category==='all'||x.group===category)&&`${x.zh} ${x.en} ${x.desc}`.toLowerCase().includes(query.toLowerCase())));
 const popular=['merge','split','compress','to_docx','ocr','images_pdf'];
 const toolIcon=(id:string)=>({merge:Merge,split:Scissors,rotate:RotateCw,compress:Minimize2,ocr:ScanText,to_docx:FileText,images_pdf:Image}[id]||FileText);
 const toolColor=(id:string)=>groups.find(g=>g.id===toolById(id)?.group)?.color||'blue';
 $effect(()=>{document.documentElement.dataset.theme=theme;try{localStorage.setItem('bpdf-theme',theme);localStorage.setItem('bpdf-language',lang);}catch{}document.documentElement.lang=lang==='zh'?'zh-CN':'en';});
 function notify(s:string){toast=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast='',6500);}
 function remember(d:DocumentSession){recent=[{path:d.path,name:d.name,date:new Date().toISOString()},...recent.filter(r=>r.path!==d.path)].slice(0,12);try{localStorage.setItem('bpdf-recent',JSON.stringify(recent));}catch{}}
 async function openPaths(paths:string[],pw=''){opening=true;for(const path of paths){try{const existing=docs.find(d=>d.path===path);if(existing){activeId=existing.id;section='reader';continue;}const d=await api.open(path,pw);docs=[...docs,d];activeId=d.id;page=Number(readSetting('bpdf-page:'+d.path,'0'));page=Math.min(Math.max(page,0),d.pages-1);section='reader';remember(d);passwordPath='';password='';await tick();if(page)go(page);}catch(e){if(String(e).includes('PASSWORD_REQUIRED')){passwordPath=path;passwordError=pw?t('密码不正确，请重试。','Incorrect password. Try again.'):'';password='';}else notify(String(e));}}opening=false;}
 async function choosePDF(){if(!native){notify(t('这是界面预览。请启动 BPDF 桌面应用以处理文件。','This is a UI preview. Start the BPDF desktop app to work with files.'));return;}try{const files=await open({multiple:true,filters:[{name:'PDF',extensions:['pdf']}]});if(files)await openPaths(Array.isArray(files)?files:[files]);}catch(e){notify(String(e));}}
 async function closeDoc(id:string){if(rooms[id]&&!await confirm(t('关闭此标签将结束或退出协作。请先另存需要保留的修改，仍要关闭吗？','Closing this tab ends or leaves the collaboration. Save changes you want to keep first. Close?'),{title:'BPDF',kind:'warning'}))return;const d=docs.find(x=>x.id===id);if(d?.dirty&&!await confirm(t('这个文档有未另存的修改，仍要关闭吗？','This document has unsaved changes. Close it?'),{title:'BPDF',kind:'warning'}))return;await api.close(id);docs=docs.filter(d=>d.id!==id);delete rooms[id];if(activeId===id){activeId=docs.at(-1)?.id||'';if(!activeId)section='home';}}
 function switchDoc(id:string){flushPosition();activeId=id;section='reader';editor=null;hits=[];const d=docs.find(d=>d.id===id);page=d?Math.min(d.pages-1,Math.max(0,Number(readSetting('bpdf-page:'+d.path,'0'))||0)):0;tick().then(()=>pageView?.jump(page));}
 async function launchTool(tool:Tool){toolInputs=[];if(active&&section==='reader'&&tool.input?.includes('pdf')){try{toolInputs=[await invoke<string>('prepare_tool_input',{id:active.id})];}catch(e){notify(String(e));return;}}selectedTool=tool;}
 function go(p:number){if(!active)return;page=Math.max(0,Math.min(active.pages-1,p));tick().then(()=>{pageView?.jump(page);});}
 let positionTimer:ReturnType<typeof setTimeout>|undefined;let pendingPosition:{path:string;page:number}|undefined;
 function flushPosition(){if(pendingPosition){try{localStorage.setItem('bpdf-page:'+pendingPosition.path,String(pendingPosition.page));}catch{}pendingPosition=undefined;}}
 function visible(p:number){if(!active||view==='single'||page===p)return;page=p;if(pendingPosition?.path!==active.path)flushPosition();pendingPosition={path:active.path,page:p};clearTimeout(positionTimer);positionTimer=setTimeout(flushPosition,250);}
 onDestroy(()=>{clearTimeout(positionTimer);flushPosition();});
 function zoom(delta:number){scale=Math.min(2.5,Math.max(.25,Math.round((scale+delta)*100)/100));}
 function fit(){if(!active||!viewport)return;const b=active.bounds[page];scale=Math.min(2.5,(viewport.clientWidth-80)/((b[2]-b[0])*(view==='spread'?2:1)));}
 async function saveCopy(){if(!active)return;const d=active;try{const out=await save({defaultPath:d.name.replace(/\.pdf$/i,'')+'-edited.pdf',filters:[{name:'PDF',extensions:['pdf']}]});if(out){await api.save(d.id,out);docs=docs.map(x=>x.id===d.id?{...x,dirty:false}:x);notify(t('已另存，原文件未修改。','Saved a copy. The original is unchanged.'));}}catch(e){notify(String(e));}}
 async function history(direction:string){if(!active||rooms[active.id])return;try{const d=await api.history(active.id,direction);docs=docs.map(x=>x.id===d.id?d:x);editor=null;}catch(e){notify(String(e));}}
 async function selection(e:Record<string,any>){if(['highlight','ink','widget'].includes(e.kind)){await apply(e);}else editor={...e,baseRevision:active?.revision};}
 async function apply(edit:Record<string,unknown>){if(!active||editing)return;const id=active.id;const selected=editor;editing=true;try{const d=await api.edit(id,edit,typeof edit.baseRevision==='number'?edit.baseRevision:active.revision);docs=docs.map(x=>x.id===d.id?d:x);if(activeId===id&&editor===selected)editor=null;}catch(e){notify(String(e).includes('COLLAB_CONFLICT')?t('此页面已有其他修改。请保留草稿并重新选择内容，避免覆盖他人的修改。','This page changed. Keep your draft and reselect the content to avoid overwriting others.'):String(e).includes('FONT_SYNC')?t('原字体不包含新增字符，或该区域包含多种字体。请选择替代字体后重试。','The original font lacks a character or this area has mixed fonts. Choose a replacement font.'):String(e).includes('TEXT_OVERFLOW')?t('文字超出所选区域，请扩大高度或减小字号。','Text exceeds the selected area. Increase its height or reduce the font size.'):String(e));}finally{editing=false;}}
 async function replaceImage(){const p=await open({filters:[{name:'Images',extensions:['png','jpg','jpeg','webp','bmp']}],multiple:false});if(typeof p==='string'&&editor)editor={...editor,path:p};}
 async function doSearch(){if(!active||!searchQuery)return;searching=true;try{hits=await api.search(active.id,searchQuery);if(hits.length)go(hits[0].page);}catch(e){notify(String(e));}finally{searching=false;}}
 function flattenOutline(items:any[],depth=0):{title:string;page:number;depth:number}[]{return items.flatMap(x=>[{title:x.title,page:typeof x.page==='number'?x.page:typeof x.page?.page==='number'?x.page.page:0,depth},...flattenOutline(x.down||x.children||[],depth+1)]);}
 async function print(){if(!active)return;try{await api.print(active.id);notify(t('已打开系统 PDF 预览，请在预览中选择打印。','Opened the system PDF preview. Choose Print there.'));}catch(e){notify(String(e));}}
 function key(e:KeyboardEvent){if(native&&isMac&&e.metaKey)return;const input=e.target instanceof HTMLElement&&['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(e.key==='Escape'){selectedTool=null;showSettings=false;editor=null;return;}if(e.metaKey||e.ctrlKey){if(e.key.toLowerCase()==='o'){e.preventDefault();choosePDF();}if(e.key.toLowerCase()==='k'){e.preventDefault();section='tools';tick().then(()=>document.querySelector<HTMLInputElement>('.tool-search input')?.focus());}if(e.key.toLowerCase()==='s'){e.preventDefault();saveCopy();}if(e.key.toLowerCase()==='f'&&active){e.preventDefault();sidebar=true;sideTab='search';tick().then(()=>document.querySelector<HTMLInputElement>('.doc-search input')?.focus());}if(e.key.toLowerCase()==='p'&&active){e.preventDefault();print();}if(e.key.toLowerCase()==='z'&&!input){e.preventDefault();history(e.shiftKey?'redo':'undo');}}else if(!input&&section==='reader'){if(e.key==='ArrowRight'||e.key==='PageDown')go(page+1);if(e.key==='ArrowLeft'||e.key==='PageUp')go(page-1);}}
 function joined(v:{document:DocumentSession;role:string;invitation?:string}){docs=[...docs,v.document];activeId=v.document.id;page=0;section='reader';editor=null;rooms[v.document.id]={role:v.role,invitation:v.invitation};}
 async function leaveRoom(){if(!active)return;await invoke('collaboration_leave',{id:active.id});delete rooms[active.id];showCollaboration=false;}
 async function syncRooms(force=false){if(editing)return;await Promise.all(Object.keys(rooms).map(async id=>{if(roomSyncs.has(id)||(!force&&(rooms[id].nextRetry||0)>Date.now()))return;roomSyncs.add(id);rooms[id]={...rooms[id],syncing:true};try{const d=await syncQueue.run(()=>invoke<DocumentSession>('collaboration_sync',{id}));if(!rooms[id])return;docs=docs.map(old=>old.id===id&&old.revision<d.revision?d:old);rooms[id]={...rooms[id],error:undefined,failures:0,nextRetry:0,lastSync:Date.now()};}catch(e){if(rooms[id]){const failures=(rooms[id].failures||0)+1;rooms[id]={...rooms[id],error:String(e),failures,nextRetry:Date.now()+Math.min(30000,2000*2**Math.min(failures,4))};}}finally{roomSyncs.delete(id);if(rooms[id])rooms[id]={...rooms[id],syncing:false};}}));}
 function keepDraft(){if(editor&&active){if(typeof editor.text==='string')drafts[active.id]=editor.text;editor=null;}}

 function validGithub(value:string){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='github.com'&&u.pathname.split('/').filter(Boolean).length>=2&&!u.username&&!u.password;}catch{return false;}}
 async function openGithub(){if(!validGithub(githubUrl)){showSettings=true;notify(t('请在设置中填写项目的 GitHub 仓库链接。','Set the project GitHub repository in Settings.'));return;}try{await openUrl(githubUrl);}catch(e){notify(String(e));}}
 $effect(()=>{if(validGithub(githubUrl))localStorage.setItem('bpdf-github',githubUrl);});
 async function menuAction(action:string){
  if(action==='settings'){showSettings=true;return;}if(action==='open'){await choosePDF();return;}
  if(action==='tools'){section='tools';await tick();document.querySelector<HTMLInputElement>('.tool-search input')?.focus();return;}
  if(action==='tasks'){section='tasks';return;}if(action==='share'){showCollaboration=true;return;}if(action==='github'){await openGithub();return;}
  if(action==='undo'||action==='redo'){const el=document.activeElement;if(el instanceof HTMLElement&&(el.matches('input,textarea')||el.isContentEditable)){document.execCommand(action);return;}await history(action);return;}
  if(!active)return;
  if(action==='close-tab'){await closeDoc(active.id);return;}if(action==='save'){await saveCopy();return;}if(action==='print'){await print();return;}
  section='reader';await tick();
  if(action==='find'){sidebar=true;sideTab='search';await tick();document.querySelector<HTMLInputElement>('.doc-search input')?.focus();}
  if(action==='zoom-in')zoom(.1);if(action==='zoom-out')zoom(-.1);if(action==='fit')fit();if(action==='sidebar')sidebar=!sidebar;
  if(action==='previous')go(page-1);if(action==='next')go(page+1);
 }
 $effect(()=>{if(native&&isMac)invoke('update_native_menu',{language:lang,hasDocument:!!active}).catch(e=>notify(String(e)));});
 onMount(()=>{if(!native||!isMac)return;let ended=false;let stop:(()=>void)|undefined;listen<string>('menu-action',e=>{menuAction(e.payload).catch(e=>notify(String(e)));}).then(fn=>{if(ended)fn();else stop=fn;});return()=>{ended=true;stop?.();};});
 onMount(()=>{const timer=setInterval(()=>syncRooms(),2000);return()=>clearInterval(timer);});
 onMount(()=>{try{recent=JSON.parse(readSetting('bpdf-recent','[]'));}catch{}if(!native)return;const cleanups:(()=>void)[]=[];let ended=false;(async()=>{try{caps=await api.capabilities();taskList=await api.tasks();const a=await listen<Task>('task-updated',e=>{taskList=[...taskList.filter(t=>t.id!==e.payload.id),e.payload].slice(-200);});const b=await listen<string[]>('open-files',e=>openPaths(e.payload));const c=await getCurrentWebviewWindow().onDragDropEvent(e=>{dropActive=e.payload.type==='enter'||e.payload.type==='over';if(e.payload.type==='drop'){dropActive=false;openPaths(e.payload.paths.filter(p=>p.toLowerCase().endsWith('.pdf')));}});const close=await getCurrentWebviewWindow().onCloseRequested(async event=>{flushPosition();if(docs.some(d=>d.dirty)||running||Object.keys(rooms).length){event.preventDefault();if(await confirm(t('还有未另存的修改或正在执行的任务。退出将放弃这些修改并取消任务，仍要退出吗？','Unsaved changes or tasks remain. Quit and discard changes and cancel tasks?'),{title:'BPDF',kind:'warning'}))await invoke('quit_application');}});cleanups.push(a,b,c,close);if(ended)cleanups.forEach(c=>c());const launch=await invoke<string[]>('launch_files');if(launch.length)openPaths(launch);}catch(e){notify(String(e));}})();return()=>{ended=true;cleanups.forEach(c=>c());};});
</script>
<svelte:window onkeydown={key}/>
<div class="app-shell" class:mac={isMac} class:reading={section==='reader'}>
 {#if section!=='reader'}<div class="window-drag-handle" data-tauri-drag-region aria-hidden="true"></div>{/if}

 <div class="workspace">
  <nav class="rail" aria-label={t('主导航','Main navigation')}><button class:active={section==='home'} class="rail-button" title={t('主页','Home')} onclick={()=>section='home'}><BookOpen size={21}/><span>{t('主页','Home')}</span></button><button class:active={section==='tools'} class="rail-button" title={t('全部工具','All tools')} onclick={()=>section='tools'}><Grid2X2 size={21}/><span>{t('工具','Tools')}</span></button><button class:active={section==='tasks'} class="rail-button" title={t('任务','Tasks')} onclick={()=>section='tasks'}><div class="badge-wrap"><Clock3 size={21}/>{#if running}<b>{running}</b>{/if}</div><span>{t('任务','Tasks')}</span></button>{#if docs.length}<div class="rail-separator"></div><button class:active={section==='reader'} class="rail-button" title={t('阅读','Read')} onclick={()=>section='reader'}><FileText size={21}/><span>{t('阅读','Read')}</span></button>{/if}<button class="rail-button" title={t('局域网协作','LAN collaboration')} onclick={()=>showCollaboration=true}><Users size={20}/><span>{t('协作','Share')}</span></button><div class="rail-bottom"><button class="rail-button" title={t('设置','Settings')} onclick={()=>showSettings=true}><Settings2 size={20}/><span>{t('设置','Settings')}</span></button></div></nav>
  <main>
   {#if section==='home'}
    <div class="home-page"><div class="home-heading"><h1>Better PDF</h1><p>Make PDF better</p></div>
     <button class="open-zone" onclick={choosePDF}><div class="paper-art"><div class="paper-back"></div><div class="paper-front"><span class="paper-corner"></span><span class="paper-label">PDF</span><i></i><i></i><i></i></div><span class="paper-plus"><Plus size={21}/></span></div><div class="open-copy"><strong>{t('打开一份 PDF','Open a PDF')}</strong><span>{t('或将文件拖到这里，开始阅读','Or drop a file here to start reading')}</span><small>{t('默认本地处理，协作由你开启','Local by default. Share only when you choose.')}</small></div><span class="open-button"><FolderOpen size={17}/>{t('选择文件','Choose a file')}<kbd>⌘ O</kbd></span></button>
     <div class="section-heading"><h2>{t('常用工具','Everyday essentials')}</h2><button class="text-button" onclick={()=>section='tools'}>{t('查看全部 34 个工具','Explore all 34 tools')}<ArrowRight size={15}/></button></div>
     <div class="quick-grid">{#each popular as id}{@const tool=toolById(id)}{@const Icon=toolIcon(id)}<button class="quick-card" onclick={()=>launchTool(tool)}><span class="tool-icon {toolColor(id)}"><Icon size={21}/></span><strong>{tool[lang==='zh'?'zh':'en']}</strong><span>{tool[lang==='zh'?'desc':'descEn']}</span><ArrowUpRight size={15} class="card-arrow"/></button>{/each}</div>
     <div class="section-heading recent-heading"><h2>{t('最近打开','Recently opened')}</h2>{#if recent.length}<button class="text-button subdued" onclick={()=>{recent=[];localStorage.removeItem('bpdf-recent');}}>{t('清空记录','Clear history')}</button>{/if}</div>
     {#if recent.length}<div class="recent-list">{#each recent as file}<button onclick={()=>openPaths([file.path])}><span class="recent-file-icon"><FileText size={19}/></span><span class="recent-name"><strong>{file.name}</strong><small>{file.path}</small></span><time>{new Date(file.date).toLocaleDateString(lang==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric'})}</time><ChevronRight size={16}/></button>{/each}</div>{:else}<div class="recent-empty"><Clock3 size={18}/><span>{t('打开过的文档会出现在这里','Your recently opened documents will appear here')}</span></div>{/if}
     <footer class="home-footer"><button class="text-button" onclick={openGithub}><Github size={15}/> GitHub</button><small>BPDF · 0.1.0</small></footer>
    </div>
   {:else if section==='tools'}
    <div class="tools-page"><div class="page-heading"><div><span class="eyebrow">A TOOL FOR EVERY PAGE</span><h1>{t('所有工具','All tools')}</h1><p>{t('小而专注的工具，处理文档的每一种需要。','Purposeful tools for every part of your document workflow.')}</p></div><label class="tool-search"><Search size={17}/><input bind:value={query} placeholder={t('搜索工具…','Search tools…')}/><kbd>⌘ K</kbd></label></div><div class="filter-chips"><button class:chosen={category==='all'} onclick={()=>category='all'}>{t('全部','All')} <small>34</small></button>{#each groups as g}<button class:chosen={category===g.id} onclick={()=>category=g.id}>{g[lang==='zh'?'zh':'en']}</button>{/each}</div>
     {#each groups as group}{@const items=filteredTools.filter(t=>t.group===group.id)}{#if items.length}<section class="tool-group"><h2><span class="group-dot {group.color}"></span>{group[lang==='zh'?'zh':'en']}<small>{items.length}</small></h2><div class="tools-grid">{#each items as tool}{@const Icon=toolIcon(tool.id)}<button class="tool-card" onclick={()=>launchTool(tool)}><span class="tool-icon {group.color}"><Icon size={20}/></span><div><strong>{tool[lang==='zh'?'zh':'en']}</strong><p>{tool[lang==='zh'?'desc':'descEn']}</p></div><ChevronRight size={15}/></button>{/each}</div></section>{/if}{/each}{#if !filteredTools.length}<div class="empty-state"><Search size={35}/><h2>{t('没有找到匹配的工具','No matching tools')}</h2><button class="text-button" onclick={()=>{query='';category='all';}}>{t('清除筛选','Clear filters')}</button></div>{/if}
    </div>
   {:else if section==='tasks'}
    <div class="tasks-page"><div class="page-heading"><div><span class="eyebrow">WORKING QUIETLY, LOCALLY</span><h1>{t('处理任务','Your tasks')}</h1><p>{t('转换在后台进行，你可以继续阅读。','Conversions run in the background while you keep reading.')}</p></div></div>{#if !taskList.length}<div class="empty-state"><Clock3 size={40} strokeWidth={1.2}/><h2>{t('这里还很安静','Nothing in the queue')}</h2><p>{t('从工具中开始一个任务，进度和结果会出现在这里。','Start with a tool. Progress and results will appear here.')}</p><button class="primary" onclick={()=>section='tools'}>{t('浏览工具','Explore tools')}<ArrowRight size={16}/></button></div>{/if}
    <div class="task-list">{#each [...taskList].reverse() as task}<article class="task-card"><div class="task-state" class:success={task.state==='completed'} class:failure={task.state==='failed'}>{#if task.state==='completed'}<CheckCircle2 size={24}/>{:else if task.state==='failed'}<XCircle size={24}/>{:else if task.state==='cancelled'}<X size={24}/>{:else}<LoaderCircle size={24} class="spin"/>{/if}</div><div class="task-body"><div class="task-heading"><strong>{toolById(task.tool)?.[lang==='zh'?'zh':'en']||task.tool}</strong><span>{t(({completed:'已完成',failed:'失败',cancelled:'已取消',running:'处理中',queued:'等待中'}as Record<string,string>)[task.state],task.state)}</span></div>{#if task.state==='running'||task.state==='queued'}<div class="progress-track"><div style:width="{Math.max(2,task.progress*100)}%"></div></div>{/if}<p class:task-error={task.state==='failed'}>{task.message}</p>{#each task.warnings as warning}<p class="task-warning">{warning}</p>{/each}{#each task.outputs as path}<button class="text-button output-link" onclick={()=>revealItemInDir(path)}><FolderOpen size={15}/>{path.split(/[\\/]/).pop()}<ArrowUpRight size={14}/></button>{/each}</div>{#if task.state==='running'||task.state==='queued'}<button class="secondary" onclick={()=>api.cancel(task.id)}>{t('取消','Cancel')}</button>{/if}</article>{/each}</div></div>
   {:else if section==='reader'&&active}
    <div class="reader-shell"><div class="document-tabs" data-tauri-drag-region>{#each docs as doc}<div class:current={doc.id===activeId} class="document-tab"><button onclick={()=>switchDoc(doc.id)}><FileText size={15}/><span>{doc.name}</span>{#if doc.dirty}<b class="dirty-dot"></b>{/if}</button><button title={t('关闭文档','Close document')} onclick={()=>closeDoc(doc.id)}><X size={13}/></button></div>{/each}<button class="icon-button" title={t('打开文档','Open document')} onclick={choosePDF}><Plus size={17}/></button></div>
     <div class="reader-content">
      {#if sidebar}<aside class="document-sidebar"><div class="side-tabs"><button class:chosen={sideTab==='pages'} title={t('页面','Pages')} onclick={()=>sideTab='pages'}><Layers size={17}/></button><button class:chosen={sideTab==='outline'} title={t('目录','Outline')} onclick={()=>sideTab='outline'}><List size={17}/></button><button class:chosen={sideTab==='search'} title={t('搜索','Search')} onclick={()=>sideTab='search'}><Search size={17}/></button></div><div class="side-scroll">{#if sideTab==='pages'}{#key active.id}<ThumbnailPages doc={active} {page} onselect={go}/>{/key}{:else if sideTab==='outline'}{#each flattenOutline(active.outline) as item}<button class="outline-item" style:padding-left="{14+item.depth*12}px" onclick={()=>go(item.page)}>{item.title}</button>{:else}<p class="side-empty">{t('文档没有目录','No document outline')}</p>{/each}{:else}<form class="doc-search" onsubmit={e=>{e.preventDefault();doSearch();}}><input bind:value={searchQuery} placeholder={t('查找文字…','Find text…')}/><button class="icon-button" type="submit" disabled={searching}><Search size={16}/></button></form>{#if searching}<div class="side-empty"><span class="spinner"></span></div>{/if}{#each hits as hit}<button class="search-result" onclick={()=>go(hit.page)}><strong>{t('第','Page')} {hit.page+1} {t('页','')}</strong><span>{searchQuery}</span></button>{/each}{/if}</div></aside>{/if}
      <div class="page-viewport" bind:this={viewport}>{#key active.id}<ReaderPages bind:this={pageView} doc={active} {scale} {mode} {view} {page} {viewport} onselect={selection} onvisible={visible} onerror={notify}/>{/key}</div>
      {#if editor}<aside class="edit-inspector"><div class="field-heading"><strong>{t(editor.kind==='text'?'编辑文字':editor.kind==='image'?'编辑图片':'添加批注',editor.kind==='text'?'Edit text':editor.kind==='image'?'Edit image':'Add note')}</strong><button class="icon-button" onclick={()=>editor=null}><X size={16}/></button></div>{#if rooms[active.id]&&editor.baseRevision!==active.revision}<p class="hint">{t('共享文档有新修改。同页内容可能需要重新选择；其他页修改不影响提交。','The shared document has changed. Reselect if this page changed; other pages do not block your edit.')}</p><button class="secondary" onclick={keepDraft}>{t('保留草稿并重新选择','Keep draft and reselect')}</button>{/if}{#if editor.kind!=='image'&&drafts[active.id]!==undefined}<button class="text-button" onclick={()=>{if(editor)editor.text=drafts[active.id];delete drafts[active.id];}}>{t('恢复保留的文字草稿','Restore saved text draft')}</button>{/if}{#if editor.kind!=='image'}<label>{t('内容','Content')}<textarea rows="6" bind:value={editor.text}></textarea></label>{/if}{#if editor.kind==='text'}<label>{t('字体','Font')}<select bind:value={editor.font}>{#if editor.sourceFont}<option value="__original__">{t('同步原字体','Match original')} · {editor.sourceFont}</option>{/if}<option value="zh-Hans">{t('内置中文字体','Bundled Chinese font')}</option><option value="Helvetica">Helvetica</option><option value="Times-Roman">Times Roman</option><option value="Courier">Courier</option></select></label><label>{t('字号','Font size')}<input type="number" min="4" max="200" bind:value={editor.size}/></label><label>{t('颜色','Color')}<input type="color" value={'#'+(editor.color||[0,0,0]).map((c:number)=>Math.round(c*255).toString(16).padStart(2,'0')).join('')} onchange={e=>{const c=e.currentTarget.value;editor={...editor,color:[parseInt(c.slice(1,3),16)/255,parseInt(c.slice(3,5),16)/255,parseInt(c.slice(5,7),16)/255]};}}/></label><p class="hint">{t('默认同步原字体、字号与颜色。原字体缺字时会提示选择替代字体。','Matches the original font, size and color. Missing glyphs require choosing a replacement font.')}</p>{/if}{#if editor.kind==='image'}<button class="secondary" onclick={replaceImage}><Image size={16}/>{t('选择替换图片','Choose replacement')}</button>{#if editor.path}<p class="hint">{editor.path.split(/[\\/]/).pop()}</p>{/if}{/if}{#if editor.targetRect}<div class="option-grid">{#each ['X','Y',t('右边界','Right'),t('下边界','Bottom')] as label,i}<label>{label}<input type="number" step="1" bind:value={editor.targetRect[i]}/></label>{/each}</div>{/if}<button class="primary" disabled={editing} onclick={()=>editor&&apply($state.snapshot(editor))}>{#if editing}<LoaderCircle size={15} class="spin"/>{:else}<Check size={15}/>{/if}{t('应用修改','Apply changes')}</button>{#if editor.kind==='image'}<button class="text-button danger" disabled={editing} onclick={()=>editor&&apply({...$state.snapshot(editor),remove:true})}>{t('删除这张图片','Delete this image')}</button>{/if}</aside>{/if}
     </div>     <div class="reader-toolbar"><div class="toolbar-group"><button class:pressed={sidebar} class="icon-button" title={t('侧边栏','Sidebar')} onclick={()=>sidebar=!sidebar}><PanelLeft size={18}/></button><button class="icon-button" title={t('上一页','Previous page')} disabled={page===0} onclick={()=>go(page-1)}><ChevronLeft size={18}/></button><input class="page-number" aria-label={t('页码','Page number')} type="number" min="1" max={active.pages} value={page+1} onchange={e=>go(Number(e.currentTarget.value)-1)}/><span class="page-count">/ {active.pages}</span><button class="icon-button" title={t('下一页','Next page')} disabled={page===active.pages-1} onclick={()=>go(page+1)}><ChevronRight size={18}/></button></div><div class="toolbar-group zoom-group"><button class="icon-button" title={t('缩小','Zoom out')} onclick={()=>zoom(-.1)}><ZoomOut size={17}/></button><button class="zoom-label" title={t('适合宽度','Fit width')} onclick={fit}>{Math.round(scale*100)}%</button><button class="icon-button" title={t('放大','Zoom in')} onclick={()=>zoom(.1)}><ZoomIn size={17}/></button><select class="view-select" aria-label={t('阅读模式','View mode')} bind:value={view}><option value="continuous">{t('连续','Continuous')}</option><option value="single">{t('单页','Single page')}</option><option value="spread">{t('双页','Two pages')}</option></select></div><div class="toolbar-group toolbar-right">{#if rooms[active.id]}<button class="text-button" title={rooms[active.id].error||t('协作已连接','Connected')} onclick={()=>showCollaboration=true}><Users size={15}/>{rooms[active.id].error?t('连接中断','Offline'):t('协作中','Shared')}</button>{/if}<button class="text-button" class:pressed={editTools} onclick={()=>{editTools=!editTools;if(!editTools){mode='read';editor=null;}}}><PenLine size={16}/>{t('编辑','Edit')}</button><button class="icon-button" title={t('撤销','Undo')} disabled={!active.canUndo||editing||!!rooms[active.id]} onclick={()=>history('undo')}><Undo2 size={17}/></button><button class="icon-button" title={t('重做','Redo')} disabled={!active.canRedo||editing||!!rooms[active.id]} onclick={()=>history('redo')}><Redo2 size={17}/></button><span class="toolbar-divider"></span><button class="icon-button" title={t('系统打印预览','System print preview')} onclick={print}><Printer size={17}/></button><button class="primary small" onclick={saveCopy}><Download size={15}/>{t('另存为','Save a copy')}</button></div></div>
     {#if editTools}<div class="edit-toolbar"><div class="mode-buttons">{#each [{id:'read',zh:'阅读',en:'Read',icon:MousePointer2},{id:'text',zh:'编辑文字',en:'Text',icon:Type},{id:'image',zh:'图片',en:'Images',icon:Image},{id:'highlight',zh:'高亮',en:'Highlight',icon:Highlighter},{id:'note',zh:'批注',en:'Notes',icon:MessageSquare},{id:'ink',zh:'手绘',en:'Draw',icon:PenLine},{id:'form',zh:'表单',en:'Forms',icon:SquareCheck}] as item}{@const Icon=item.icon}<button class:chosen={mode===item.id} onclick={()=>{mode=item.id;editor=null;}}><Icon size={15}/>{item[lang==='zh'?'zh':'en']}</button>{/each}</div><button class="text-button" onclick={()=>section='tools'}><Grid2X2 size={15}/>{t('全部工具','All tools')}</button></div>{/if}
<footer class="reader-status"><span>{active.name}</span><span>{mode==='text'?t('点击文字编辑；双击空白处添加文字','Click text to edit; double-click blank space to add text'):mode==='image'?t('点击图片进行替换或删除','Click an image to replace or delete'):mode==='highlight'?t('点击一行文字以高亮','Click a text line to highlight'):mode==='ink'?t('在页面上拖动绘制','Drag on the page to draw'):t('原文件未修改','Original file unchanged')}</span><span>{active.pages} {t('页','pages')}</span></footer>
    </div>
   {/if}
  </main>
 </div>
</div>
{#if selectedTool}<ToolDialog tool={selectedTool} {lang} initial={toolInputs} onclose={()=>selectedTool=null} onsubmit={()=>{section='tasks';api.tasks().then(t=>taskList=t);}} onerror={notify}/>{/if}
{#if toast}<div class="toast" role="status"><span>{toast}</span><button class="icon-button" onclick={()=>toast=''}><X size={15}/></button></div>{/if}
{#if opening}<div class="opening-indicator"><LoaderCircle size={17} class="spin"/>{t('正在打开文档…','Opening document…')}</div>{/if}
{#if dropActive}<div class="drop-overlay"><FileText size={48}/><h2>{t('放开，开始阅读','Drop to start reading')}</h2></div>{/if}
{#if passwordPath}<div class="modal-backdrop"><form class="compact-dialog" onsubmit={e=>{e.preventDefault();openPaths([passwordPath],password);}}><h2>{t('打开受保护的文档','Open a protected document')}</h2><p>{passwordPath.split(/[\\/]/).pop()}</p><label>{t('打开密码','Opening password')}<input type="password" bind:value={password} autocomplete="off"/></label>{#if passwordError}<p class="error-message">{passwordError}</p>{/if}<div class="button-row"><button type="button" class="secondary" onclick={()=>passwordPath=''}>{t('取消','Cancel')}</button><button class="primary" type="submit">{t('打开','Open')}</button></div></form></div>{/if}
{#if showSettings}<div class="modal-backdrop"><div class="compact-dialog settings-dialog" role="dialog" aria-modal="true" aria-label={t('设置','Settings')}><div class="field-heading"><h2>{t('偏好设置','Preferences')}</h2><button class="icon-button" onclick={()=>showSettings=false}><X size={18}/></button></div><label>{t('外观','Appearance')}<div class="theme-options">{#each [{id:'light',icon:Sun,zh:'浅色',en:'Light'},{id:'dark',icon:Moon,zh:'深色',en:'Dark'},{id:'system',icon:Monitor,zh:'系统',en:'System'}]as item}{@const Icon=item.icon}<button class:chosen={theme===item.id} onclick={()=>theme=item.id}><Icon size={21}/>{item[lang==='zh'?'zh':'en']}</button>{/each}</div></label><label>{t('界面语言','Interface language')}<select bind:value={lang}><option value="zh">简体中文</option><option value="en">English</option></select></label><div class="settings-note"><ShieldCheck size={20}/><p>{t('文档在本地处理。仅开启协作时，与持有邀请码的局域网成员共享当前副本。','Documents are processed locally. Sharing sends the selected copy only to invited LAN peers.')}</p></div><div class="runtime-status"><strong>{t('内置处理组件','Bundled components')}</strong>{#each Object.entries(caps) as [name,ready]}<div><span>{name}</span><small class:ready>{ready?t('就绪','Ready'):t('未安装','Missing')}</small></div>{/each}</div><label>GitHub<input type="url" bind:value={githubUrl} placeholder="https://github.com/owner/repository"/></label><p class="settings-version">BPDF 0.1.0 · AGPL-3.0</p></div></div>{/if}

{#if showCollaboration}<CollaborationDialog {lang} draft={collaborationDraft} document={active} room={active?rooms[active.id]:undefined} onclose={()=>showCollaboration=false} onjoined={joined} onleave={leaveRoom} onretry={()=>syncRooms(true)}/>{/if}
